// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    __InvMutHandleStub handle;

    function setUp() public {
        handle = new __InvMutHandleStub();
        c = new MStableYieldSource(ISavingsContractV2(address(handle)));
    }

    function testFuzz_property(uint256 amount, address actor, address to) public {
        vm.assume(actor != address(0));
        vm.assume(to != address(0));
        amount = bound(amount, 1, type(uint128).max);

        vm.prank(actor);
        c.supplyTokenTo(amount, to);

        uint256 credited = c.imBalances(to);
        assertTrue(
            credited == handle.lastCreditsIssued() && credited > 0,
            "deposit must credit the beneficiary with the credits issued"
        );
    }
}

contract __InvMutHandleStub {
    uint256 public lastCreditsIssued;

    function underlying() external view returns (address) { return address(this); }
    function exchangeRate() external pure returns (uint256) { return 1e18; }

    function depositSavings(uint256 _amount) external returns (uint256) {
        lastCreditsIssued = _amount;
        return _amount;
    }

    function depositSavings(uint256 _amount, address) external returns (uint256) {
        lastCreditsIssued = _amount;
        return _amount;
    }

    function redeemUnderlying(uint256 _amount) external returns (uint256) { return _amount; }

    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
